import { Component, inject } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Location } from '@angular/common';
import {
  TablerIconComponent, IconArrowLeft, IconX, IconSend, IconPencil, IconRefresh, IconArrowBackUp,
} from '@tabler/icons-angular';
import { HrmButton, HrmActionBar, HrmActionBarItem, HRM_WORKFLOW_ACTIONS, HrmWorkflowStatus } from 'hrm-ui';
import { SgRequestDetail } from './sg-request-detail';
import { REQUESTS, ReqRow, ReqStatus } from './_requests';

/** Trang BẢN GHI TOÀN TRANG cho 2 template Đăng ký / Phê duyệt — đích của surface Toàn trang
 *  (điều hướng) + Tab mới (window.open) từ hrm-detail-peek. Nhận ?id= + ?kind=(register|approval),
 *  tìm trong REQUESTS, render chi tiết dùng chung (sg-request-detail) + topnav back + hành động
 *  theo vai trò. Toàn trang: topnav full-width sticky (thoát card). */
@Component({
  selector: 'sg-request-record',
  imports: [TablerIconComponent, HrmButton, HrmActionBar, SgRequestDetail],
  template: `
    <div class="lr">
      <div class="lr-nav">
        <div class="lr-nav-in">
          <div class="lr-nav-l">
            <hrm-button size="sm" [iconOnly]="true" ariaLabel="Quay lại" (click)="back()"><tabler-icon [icon]="icBack" [size]="18" /></hrm-button>
            <h1 class="lr-t">{{ row?.code ?? 'Đơn từ' }}</h1>
          </div>
          @if (row) {
            <div class="lr-nav-r"><hrm-action-bar [actions]="actions()" moreLabel="Thêm" (action)="onAction()" /></div>
          }
        </div>
      </div>

      <div class="lr-body">
        @if (row) {
          <div class="lr-card"><sg-request-detail [req]="row" /></div>
        } @else {
          <p class="lr-empty">Không tìm thấy đơn.</p>
        }
      </div>
    </div>
  `,
  host: { class: 'sg-request-record' },
  styles: [`
    :host { display: block; }
    ::ng-deep .shell-content:has(sg-request-record) { padding: 0 !important; }
    .lr { display: block; }
    .lr-nav { position: sticky; top: 0; z-index: 10; background: var(--bg-surface); border-bottom: 1px solid var(--border-sub); }
    .lr-nav-in { max-width: 1080px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); padding: var(--space-12) var(--space-4); }
    .lr-nav-l { display: flex; align-items: center; gap: var(--space-12); min-width: 0; }
    .lr-nav-r { display: flex; align-items: center; gap: var(--space-8); flex: none; min-width: 0; }
    .lr-t { margin: 0; font-size: var(--fs-20); font-weight: 600; color: var(--text-strong); white-space: nowrap; font-family: var(--font-mono, ui-monospace, monospace); }
    .lr-body { max-width: 1080px; margin: 0 auto; padding: var(--space-20) var(--space-4) var(--space-8); }
    .lr-card { background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-lg); }
    .lr-empty { color: var(--text-sub); }
  `],
})
export class SgRequestRecord {
  private readonly location = inject(Location);
  private readonly route = inject(ActivatedRoute);
  protected readonly icBack = IconArrowLeft;

  private readonly kind = this.route.snapshot.queryParamMap.get('kind') ?? 'approval';
  /** Bản ghi theo ?id= (snapshot — vào trang là điều hướng mới, component dựng lại). */
  protected readonly row: ReqRow | null = REQUESTS.find(
    (r) => String(r.id) === (this.route.snapshot.queryParamMap.get('id') ?? ''),
  ) ?? null;

  /** Hành động topnav theo vai trò + trạng thái (demo — no-op). */
  protected actions(): HrmActionBarItem[] {
    const r = this.row;
    if (!r) return [];
    if (this.kind === 'register') return this.regActions(r.status);
    if (r.status === 'draft') return [];
    return (HRM_WORKFLOW_ACTIONS[r.status as HrmWorkflowStatus] ?? []).map((a) => ({ key: a.key, label: a.vi, tone: a.tone, icon: a.icon }));
  }
  private regActions(s: ReqStatus): HrmActionBarItem[] {
    switch (s) {
      case 'draft': return [
        { key: 'submit', label: 'Gửi duyệt', tone: 'primary', icon: IconSend },
        { key: 'edit', label: 'Sửa', tone: 'neutral', icon: IconPencil },
      ];
      case 'pending': return [{ key: 'withdraw', label: 'Thu hồi', tone: 'warning', icon: IconArrowBackUp }];
      case 'rejected': return [{ key: 'resubmit', label: 'Đăng ký lại', tone: 'primary', icon: IconRefresh }];
      case 'changeRequested': return [{ key: 'edit', label: 'Chỉnh sửa & gửi lại', tone: 'primary', icon: IconPencil }];
      case 'approved': return [{ key: 'cancel', label: 'Yêu cầu hủy', tone: 'warning', icon: IconX }];
      default: return [];
    }
  }
  protected onAction(): void { /* demo no-op — trang độc lập, không giữ state in-memory */ }
  protected back(): void { this.location.back(); }
}
